head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > maxByteLength]<br/>SearchBox 컴포넌트에 입력 가능한 최대 바이트 길이를 설정합니다.",
    "validation" : [
        "스크립트로 setValue() 를 호출하여 입력값을 설정 시 maxByteLength 가 적용되지 않습니다.",
        "displayFormat 속성과 함께 설정해도 실제 입력값 기준으로 maxByteLength 가 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}



// target1 : dataType=number, maxByteLength=5, setValue(123456789), 기대값=123456789 (스크립트 setValue 는 maxByteLength 미적용)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue(123456789);
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
};

// target2 : dataType=number, maxByteLength=10, displayFormat=#,###, 직접 입력값=123456789, 기대값=실제값 123456789 / 표시 123,456,789
scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
};
